function pkadd(it){const r=document.createElement("div");r.className="pr3";r.innerHTML=`<select class="pp" onchange="pkQ(this.parentNode);pkcalc()">${pkOpts()}</select><select class="pq" onchange="pkcalc()"></select><input class="pn" type="number" min="1" step="1" value="${it?it.n:1}" oninput="pkcalc()" aria-label="Nombre de fioles"><button type="button" onclick="pkdr(this)">✕</button>`;$("pk_l").appendChild(r);if(it)r.querySelector(".pp").value=it.pid;pkQ(r,it?it.q:null);pkcalc()}
function pkdr(b){if($("pk_l").children.length>1)b.parentNode.remove();pkcalc()}
function pkItems(){const m={};[...$("pk_l").children].forEach(r=>{const pid=+r.querySelector(".pp").value,q=+r.querySelector(".pq").value,n=Math.max(1,Math.floor(+r.querySelector(".pn").value||1));if(!pid||!q)return;const k=pid+"-"+q;m[k]=m[k]||{pid,q,n:0};m[k].n+=n});return Object.values(m)}
function pkcalc(src){const it=pkItems(),d=pkInfo({items:it}),pr=$("pk_p"),rr=$("pk_r");if(!d.ok||d.tot<2){$("pk_i").textContent=d.ok?"Un pack contient au moins 2 fioles.":"";return}const base=d.base;
if(src==2||(!src&&rr.value!==""&&pr.value===""))pr.value=(Math.round(base*(1-+rr.value/100)*100)/100).toFixed(2);else if(pr.value!=="")rr.value=Math.max(0,Math.round((1-+pr.value/base)*100));
const t=+pr.value;$("pk_i").innerHTML=(t?`Prix à l'unité (${d.tot} fioles) : <b>${eur(base)}</b> → pack <b>${eur(t)}</b> ${t<base?"(−"+Math.round((1-t/base)*100)+" %)":`<span style="color:#ff6b6b">⚠ pas moins cher qu'à l'unité</span>`} · soit ${eur(t/d.tot)} / fiole`:`Prix à l'unité (${d.tot} fioles) : <b>${eur(base)}</b>`)}
function pkadm(){const cur=pkItems();$("pk_l").innerHTML="";(cur.length?cur:[null]).forEach(i=>pkadd(i||undefined));pklist()}
function pkreset(){pked=null;$("pkf").reset();$("pk_l").innerHTML="";pkadd();$("pk_c").checked=true;$("pk_i").textContent="";$("pk_s").textContent="Créer le pack";$("pk_x").style.display="none"}
function pksave(e){e.preventDefault();const it=pkItems(),d=pkInfo({items:it});if(!d.ok||d.tot<2){toast("Ajoute au moins 2 fioles au pack");return}
const o={id:pked||Date.now(),items:it,p:+(+$("pk_p").value).toFixed(2),cmd:$("pk_c").checked?1:0,dl:$("pk_d").value.trim()},nm=$("pk_t").value.trim(),bg=$("pk_b").value.trim();if(nm)o.name=nm;if(bg)o.bg=bg;
if(pked)PK[PK.findIndex(x=>x.id==pked)]=o;else PK.push(o);if(savePK()){pkreset();pklist();prender();toast("Pack enregistré ✔")}}
function pklist(){$("pkl").innerHTML=PK.length?PK.map(k=>{const d=pkInfo(k);return `<div class="ar" style="grid-template-columns:1fr auto auto"><div><b>${d.ok?esc(d.name):"Pack incomplet"}</b><small>${d.ok?esc(d.ct)+" · "+eur(k.p)+(d.base>k.p?" · −"+Math.round((1-k.p/d.base)*100)+" %":"")+(k.cmd?" · sur commande":""):`<span style="color:#ff6b6b">Un produit ou une quantité n'existe plus : pack masqué sur le site</span>`}</small></div><button onclick="pkedit(${k.id})">Modifier</button><button onclick="pkdel(${k.id},this)">Supprimer</button></div>`}).join(""):`<p class="sub">Aucun pack pour le moment.</p>`}
function pkedit(id){const k=PK.find(x=>x.id==id);if(!k)return;pked=id;$("pk_t").value=k.name||"";$("pk_l").innerHTML="";k.items.forEach(i=>pkadd(i));$("pk_p").value=k.p;$("pk_b").value=k.bg||"";$("pk_c").checked=!!k.cmd;$("pk_d").value=k.dl||"";pkcalc(1);$("pk_s").textContent="Mettre à jour";$("pk_x").style.display="";$("ad").scrollTo(0,0)}
async function pkdel(id,b){if(!b.dataset.s){b.dataset.s=1;b.textContent="Confirmer ?";setTimeout(()=>{b.dataset.s="";b.textContent="Supprimer"},3000);return}const sb=window.ULTIM_SUPABASE;if(!sb){toast("Supabase indisponible : pack non supprimé");return}b.disabled=true;b.textContent="Suppression…";try{const {data:{session}}=await sb.auth.getSession();if(String(session?.user?.email||"").toLowerCase()!=="logan.decupper1@gmail.com")throw new Error("Connecte-toi à Supabase avec le compte administrateur pour supprimer un pack.");const {error}=await sb.from("store_packs").update({published:false,updated_at:new Date().toISOString()}).eq("id",Number(id));if(error)throw error;PK=PK.filter(x=>Number(x.id)!==Number(id));if(!savePK())throw new Error("Impossible d’enregistrer la modification dans ce navigateur.");pklist();prender();toast("Pack supprimé ✔")}catch(e){b.disabled=false;b.dataset.s="";b.textContent="Supprimer";toast("Suppression impossible : "+(e?.message||"erreur Supabase"));console.error("Suppression pack:",e)}}
const CS=[["Bandeau du haut",[["bar","Texte du bandeau (*mot* = en gras)"]]],["Haut de page (hero)",[["tag","Accroche"],["h1a","Titre : début"],["h1b","Titre : mot contouré"],["h1c","Titre : mot en dégradé"],["hb1","Bouton 1"],["hb2","Bouton 2"],["s1v","Chiffre 1"],["s1l","Légende 1"],["s2v","Chiffre 2"],["s2l","Légende 2"],["s3v","Chiffre 3"],["s3l","Légende 3"]]],["Boutique",[["shopT","Titre (*mot* = coloré)"],["shopS","Sous-titre"]]],["Newsletter",[["nlT","Titre (*mot* = coloré)"],["nlS","Sous-titre"]]],["Telegram",[["tgT","Titre (*mot* = coloré)"],["tgS","Sous-titre"],["tgB","Texte du bouton"],["tgU","Lien d'invitation (https://t.me/…)"]]],["Pied de page",[["leg","Mention en bas de page"]]]];
const frQ=x=>`<div class="fr"><input class="q" value="${esc(x.q)}" placeholder="Question"><textarea class="a" rows="2" placeholder="Réponse">${esc(x.a)}</textarea><button type="button" onclick="this.parentNode.remove()">✕</button></div>`,frF=x=>`<div class="fr"><input class="i" value="${esc(x.i)}" placeholder="Icône"><input class="t" value="${esc(x.t)}" placeholder="Titre"><textarea class="a" rows="2" placeholder="Texte">${esc(x.p)}</textarea><button type="button" onclick="this.parentNode.remove()">✕</button></div>`;
function ctform(){$("ctf").innerHTML=CS.map(g=>`<h3>${g[0]}</h3>`+g[1].map(f=>`<label class="cl" style="display:block">${f[1]}<input data-k="${f[0]}" value="${esc(cv2(f[0]))}" style="max-width:none;width:100%;margin-top:4px"></label>`).join("")).join("")+`<h3>Bandeau défilant</h3><textarea id="c_tk" rows="4">${esc(cv2("tick").join("\n"))}</textarea><small style="color:var(--mu)">Un texte par ligne.</small><h3>Cases « Pourquoi nous »</h3><div id="c_ft">${cv2("feat").map(frF).join("")}</div><div><button type="button" class="btn o" style="margin:0" onclick="$('c_ft').insertAdjacentHTML('beforeend',frF({i:'',t:'',p:''}))">+ Ajouter une case</button></div><h3>Conditions générales de vente</h3><small style="color:var(--mu)">Titre : ligne commençant par ## · Liste : lignes commençant par - · Variables : {{vendeur}} {{adresse}} {{siret}} {{email}} {{mediateur}} {{tva}} {{livraison}} {{franco}} {{cb_taux}} {{cb_min}} {{cb_decl}} {{date}} {{forme}} {{telephone}} {{directeur}} {{hebergeur}} {{rw_x}} {{rw_p}} {{rw_d}} {{vir_delai}} {{wl_txt}}</small><textarea id="c_cg" rows="18">${esc(cv2("cgv"))}</textarea><h3>Mentions légales</h3><textarea id="c_ml" rows="12">${esc(cv2("mentions"))}</textarea><h3>Politique de confidentialité</h3><textarea id="c_pc" rows="16">${esc(cv2("conf"))}</textarea><h3>FAQ</h3><div id="c_fq">${cv2("faq").map(frQ).join("")}</div><div><button type="button" class="btn o" style="margin:0" onclick="$('c_fq').insertAdjacentHTML('beforeend',frQ({q:'',a:''}))">+ Ajouter une question</button></div>`}
function ctsave(){const o={};document.querySelectorAll("#ctf [data-k]").forEach(i=>{const v=i.value.trim();if(v!==DF[i.dataset.k])o[i.dataset.k]=v});
const tk=$("c_tk").value.split("\n").map(x=>x.trim()).filter(Boolean);if(tk.join("|")!==DF.tick.join("|"))o.tick=tk;
const ft=[...$("c_ft").children].map(r=>({i:r.querySelector(".i").value.trim(),t:r.querySelector(".t").value.trim(),p:r.querySelector(".a").value.trim()})).filter(x=>x.t||x.p);if(JSON.stringify(ft)!=JSON.stringify(DF.feat))o.feat=ft;
const fq=[...$("c_fq").children].map(r=>({q:r.querySelector(".q").value.trim(),a:r.querySelector(".a").value.trim()})).filter(x=>x.q&&x.a);if(JSON.stringify(fq)!=JSON.stringify(DF.faq))o.faq=fq;
const cg=$("c_cg").value;if(cg.trim()!==DF.cgv.trim())o.cgv=cg;const ml=$("c_ml").value;if(ml.trim()!==DF.mentions.trim())o.mentions=ml;const pc=$("c_pc").value;if(pc.trim()!==DF.conf.trim())o.conf=pc;try{localStorage.setItem("up_ct",JSON.stringify(o))}catch(e){toast("Stockage plein");return}CT=o;applyCT();toast("Contenu enregistré ✔")}
function ctreset(){CT={};try{localStorage.removeItem("up_ct")}catch(e){}applyCT();ctform();toast("Textes d'origine rétablis")}
// produits sur commande
const DEFT=[[3,5],[6,10],[10,15]];
const coTiers=c=>(Array.isArray(c.tiers)?c.tiers:DEFT).filter(t=>t[0]>0&&t[1]>0).sort((a,b)=>a[0]-b[0]);
function coOpts(f){if(f.s=="all"){const o=[];P.filter(p=>!p.co).forEach(p=>p.v.forEach(v=>o.push({t:"p"+p.id+"_"+v.q,g:p.n,l:p.n+" · "+fq(v.q),p:Math.round(v.p*(1-(+f.r||0)/100)*100)/100})));return o}return(f.opts||[]).map((x,i)=>({t:"o"+i,l:x.l+(+x.q?" · "+fq(x.q):""),p:+x.p||0}))}
function coMin(p){try{const c=p.co;return Math.round(((+c.base||0)+c.f.reduce((a,f)=>{if(f.o)return a;const o=coOpts(f);return a+(o.length?Math.min(...o.map(x=>x.p)):0)},0))*100)/100}catch(e){return 0}}
function coBuild(p,tk){try{const c=p.co;let pr=+c.base||0,ms=0,un=0;const ct=[];
for(let i=0;i<c.f.length;i++){const f=c.f[i],t=tk[i];
if(f.mq){const parts=[];let n=0,sm=0;for(const z of String(t||"").split(",").filter(Boolean)){const[tok,q]=z.split("*"),op=coOpts(f).find(y=>y.t==tok),qq=Math.floor(+q);if(!op||!(qq>0)||qq>99)return null;n+=qq;sm+=op.p*qq;parts.push(qq+" × "+op.l)}
if(!n){if(f.o)continue;return null}un+=n;ms+=sm;ct.push(f.l+" : "+parts.join(" · "))}
else{if(t==null||t==""||t=="x"){if(f.o)continue;return null}const op=coOpts(f).find(z=>z.t==t);if(!op)return null;pr+=op.p;ct.push(f.l+" : "+op.l)}}
const tr=coTiers(c).filter(x=>un>=x[0]).pop(),pct=tr?tr[1]:0,ds=Math.round(ms*pct)/100;pr+=ms-ds;if(pct)ct.push("Remise volume −"+pct+" %");
return{name:p.n,price:Math.round(pr*100)/100,ct:ct.join(" · "),un,pct,ds,ms}}catch(e){return null}}
function coSel(c,f){const o=coOpts(f),pl=c.base>0||c.f.length>1,tx=x=>x.l+" — "+(pl?"+":"")+eur(x.p);let h=f.o?`<option value="x">— Aucun —</option>`:"";
if(f.s=="all"){const g={};o.forEach(x=>(g[x.g]=g[x.g]||[]).push(x));h+=Object.entries(g).map(([k,a])=>`<optgroup label="${esc(k)}">${a.map(x=>`<option value="${x.t}">${esc(tx(x))}</option>`).join("")}</optgroup>`).join("")}else h+=o.map(x=>`<option value="${x.t}">${esc(tx(x))}</option>`).join("");return h}
function coMqRows(f){let g="",h="";coOpts(f).forEach(x=>{if(f.s=="all"&&x.g!=g){g=x.g;h+=`<div class="qg">${esc(g)}</div>`}h+=`<div class="qrow"><b>${esc(f.s=="all"?x.l.slice(x.g.length+3):x.l)}</b><span class="qp">${eur(x.p)}</span><div class="qs"><button type="button" onclick="coQ(this,-1)">−</button><span class="qv" data-t="${x.t}">0</span><button type="button" onclick="coQ(this,1)">+</button></div></div>`});return h||`<p class="sub" style="padding:12px">Aucun produit disponible.</p>`}
const coTk=()=>[...document.querySelectorAll("#md .cfld")].map(x=>{const s=x.querySelector("select");return s?s.value:[...x.querySelectorAll(".qv")].filter(e=>+e.textContent>0).map(e=>e.dataset.t+"*"+(+e.textContent)).join(",")});
function coOpen(id){const p=P.find(x=>x.id==id),c=p.co;cur={id};$("md").innerHTML=`<button class="x" onclick="closeAll()">✕</button><div class="vis">${pimg(p)}</div><div class="mi"><small style="font:700 15px var(--fc);letter-spacing:.2em;color:var(--b2);text-transform:uppercase">${esc(p.c)}</small><h3>${esc(p.n)}</h3><div class="st" style="color:#ff9f43">⏳ Sur commande${c.dl?" · "+esc(c.dl):""}</div><p>${esc(p.d)}</p>${c.f.map(f=>`<div class="cfld"><label style="font:700 14px var(--fc);letter-spacing:.14em;color:var(--mu);text-transform:uppercase">${esc(f.l)}</label>${f.mq?`<details class="cmq" open><summary>${f.s=="all"?"Choisis tes produits et leurs quantités":"Choisis tes quantités"} <span class="cqn">(0 sélectionné)</span></summary><div class="cmb">${coMqRows(f)}</div></details>`:`<div class="opt"><select class="cof" onchange="coCalc()" style="flex:1">${coSel(c,f)}</select></div>`}</div>`).join("")}<div id="cod" class="sub" style="margin:0 0 8px;font-size:13px"></div><div class="pr" style="margin:0 0 6px"><b id="pp"></b></div><button class="btn" style="width:100%;text-align:center" onclick="coAdd()">Valider et ajouter au panier</button></div>`;coCalc();$("md").classList.add("on");$("ov").classList.add("on")}
function coQ(b,d){const s=b.parentNode.querySelector(".qv");s.textContent=Math.max(0,Math.min(99,(+s.textContent||0)+d));coCalc()}
function coCalc(){const p=P.find(x=>x.id==cur.id),c=p.co,r=coBuild(p,coTk()),tr=coTiers(c);$("pp").innerHTML=r?eur(r.price)+(r.ds>0?`<s>${eur(r.price+r.ds)}</s>`:""):"—";
if(c.f.some(f=>f.mq)){const u=[...document.querySelectorAll("#md .qv")].reduce((a,e)=>a+(+e.textContent||0),0),nx=tr.find(x=>x[0]>u);
$("cod").innerHTML=(u?`<b>${u} produit${u>1?"s":""}</b> sélectionné${u>1?"s":""}`+(r&&r.pct?` · remise −${r.pct} % (−${eur(r.ds)})`:""):"Sélectionne tes produits dans le menu ci-dessus.")+(nx?`<br>🎁 Encore ${nx[0]-u} produit${nx[0]-u>1?"s":""} pour −${nx[1]} %`:"")+(tr.length?`<br><span style="color:var(--mu)">${tr.map(x=>"−"+x[1]+" % dès "+x[0]+" produits").join(" · ")}</span>`:"")}
document.querySelectorAll("#md .cmq").forEach(dd=>{const n=[...dd.querySelectorAll(".qv")].reduce((a,e)=>a+(+e.textContent||0),0);dd.querySelector(".cqn").textContent="("+n+" sélectionné"+(n>1?"s":"")+")"})}
function coAdd(){const p=P.find(x=>x.id==cur.id),tk=coTk(),r=coBuild(p,tk);if(!r)return toast("Sélectionne au moins un produit ou complète tes choix");ins("co-"+p.id+"-"+tk.join("~"),r.name,r.price,p.col,p.id,{cmd:1,dl:p.co.dl||"",ct:r.ct});closeAll();toast("Ajouté au panier ✔");cart(1)}
function tyt(){const co=$("f_ty").value=="co";$("vwrap").style.display=co?"none":"";$("kwrap").style.display=co?"none":"";$("cowrap").style.display=co?"":"none";$("vr").querySelectorAll("input").forEach(i=>i.disabled=co);if(co&&!$("co_f").children.length)cofAdd();if(co&&!ed&&!$("co_t").children.length)DEFT.forEach(a=>cotAdd(a))}
const cofRow=o=>`<div class="vr"><input class="ol" maxlength="60" placeholder="Libellé du choix" value="${esc(o.l||"")}"><input class="oq" type="number" min="0" step="any" placeholder="mg (optionnel)" value="${o.q||""}"><input class="op" type="number" min="0" step="0.01" placeholder="Prix (€)" value="${o.p!=null?o.p:""}"><button type="button" onclick="this.parentNode.remove()">✕</button></div>`;
const cotRow=a=>`<div class="vr2"><input class="tn" type="number" min="1" step="1" placeholder="À partir de (nb de produits)" value="${a[0]||""}"><input class="tp" type="number" min="0" max="95" step="0.5" placeholder="Remise (%)" value="${a[1]||""}"><button type="button" onclick="this.parentNode.remove()">✕</button></div>`;
function cotAdd(a){$("co_t").insertAdjacentHTML("beforeend",cotRow(a||[]))}
function cofAdd(f){f=f||{s:"all",o:0,opts:[]};const d=document.createElement("div");d.className="cofe";d.innerHTML=`<div class="two"><input class="fl" maxlength="60" placeholder="Intitulé du menu (ex. Choisis ton produit)" value="${esc(f.l||"")}"><select class="fs" onchange="cofSrc(this)"><option value="all">Tous les produits du site</option><option value="list">Ma liste de choix</option></select></div><div class="fall"><input class="fr2" type="number" min="0" max="95" step="1" placeholder="Remise sur le prix des produits (%) — optionnel" value="${f.r||""}"></div><div class="flist" style="display:none"><div class="fo">${(f.s=="list"&&f.opts.length?f.opts:[{}]).map(cofRow).join("")}</div><button type="button" class="btn o" style="margin:0" onclick="this.previousElementSibling.insertAdjacentHTML('beforeend',cofRow({}))">+ Ajouter un choix</button></div><label class="cl" style="justify-content:flex-start"><input type="checkbox" class="fmq" style="width:auto" ${f.mq?"checked":""}> Le client choisit plusieurs produits avec une quantité pour chacun (remises automatiques)</label><label class="cl" style="justify-content:flex-start"><input type="checkbox" class="fo2" style="width:auto" ${f.o?"checked":""}> Menu optionnel (le client peut ne rien choisir)</label><div><button type="button" class="btn o" style="margin:0" onclick="this.closest('.cofe').remove()">Supprimer ce menu</button></div>`;$("co_f").appendChild(d);d.querySelector(".fs").value=f.s||"all";cofSrc(d.querySelector(".fs"))}
function cofSrc(x){const d=x.closest(".cofe");d.querySelector(".fall").style.display=x.value=="all"?"":"none";d.querySelector(".flist").style.display=x.value=="list"?"":"none"}
function cofRead(){return[...$("co_f").children].map(d=>{const s=d.querySelector(".fs").value;return{l:d.querySelector(".fl").value.trim(),s,r:Math.min(95,Math.max(0,+d.querySelector(".fr2").value||0)),o:d.querySelector(".fo2").checked?1:0,mq:d.querySelector(".fmq").checked?1:0,opts:s=="list"?[...d.querySelectorAll(".fo .vr")].map(r=>({l:r.querySelector(".ol").value.trim(),q:+r.querySelector(".oq").value||0,p:Math.max(0,+r.querySelector(".op").value||0)})).filter(x=>x.l):[]}})}
function cofLoad(c){$("co_f").innerHTML="";$("co_t").innerHTML="";$("co_b").value=c.base||"";$("co_d").value=c.dl||"";c.f.forEach(f=>cofAdd(f));(Array.isArray(c.tiers)?c.tiers:DEFT).forEach(a=>cotAdd(a))}
function cosave(){const F=cofRead();if(!F.length)return toast("Ajoute au moins un menu déroulant");for(const f of F){if(!f.l)return toast("Chaque menu doit avoir un intitulé");if(f.s=="list"&&!f.opts.length)return toast("Ajoute au moins un choix dans « "+f.l+" »")}
const T=[...$("co_t").children].map(r=>[Math.floor(+r.querySelector(".tn").value)||0,+r.querySelector(".tp").value||0]).filter(a=>a[0]>0&&a[1]>0).sort((a,b)=>a[0]-b[0]);
const o={id:ed||Date.now(),n:$("f_n").value.trim(),c:$("f_c").value.trim(),d:$("f_d").value.trim(),col:$("f_col").value,v:[{q:0,p:0}],co:{dl:$("co_d").value.trim(),base:Math.max(0,+$("co_b").value||0),f:F,tiers:T}},bg=$("f_b").value.trim();if(bg)o.bg=bg;if(img)o.img=img;
if(ed)P[P.findIndex(x=>x.id==ed)]=o;else P.push(o);if(store()){areset();alist();cats();render();prender();toast("Produit sur commande enregistré ✔")}}
// paiement par virement
const PAY=()=>{try{return JSON.parse(localStorage.getItem("up_pay")||"{}")||{}}catch(e){return{}}};
function ibanOk(v){v=String(v).replace(/\s+/g,"").toUpperCase();if(!/^[A-Z]{2}\d{2}[A-Z0-9]{10,30}$/.test(v)||(v.startsWith("FR")&&v.length!=27))return false;let r=0;for(const ch of v.slice(4)+v.slice(0,4))for(const d of String(/\d/.test(ch)?ch:ch.charCodeAt(0)-55))r=(r*10+ +d)%97;return r==1}
const fmtIban=v=>String(v).replace(/\s+/g,"").toUpperCase().replace(/(.{4})/g,"$1 ").trim(),payOn=()=>{const p=PAY();return !!(p.on&&p.i&&ibanOk(p.i)&&p.n)},PAYH=()=>{const h=Math.floor(+PAY().h);return h>=1?h:72},fo=(o,k)=>k=="all"||(k=="pay"?o.pay=="wait"&&o.st!="no":o.st==k);
function kuse(o,g){if(!o.pc)return;loadK();const k=K.find(x=>x.c==o.pc);if(k){k.used=Math.max(0,(k.used||0)+g);saveK()}}
function payNotice(){return payOn()?`<p class="sub" style="font-size:13px;margin:0">Paiement par <b>virement bancaire</b> : les coordonnées te sont affichées juste après la validation. Ta commande est réservée ${PAYH()} h et traitée dès réception du virement.</p>`:`<p class="sub" style="font-size:13px;margin:0">Le paiement par virement te sera précisé juste après la validation de ta commande.</p>`}
