const cv=$("bg"),cx=cv.getContext("2d");let pts=[];
function rs(){cv.width=innerWidth;cv.height=innerHeight;pts=Array.from({length:Math.min(70,innerWidth/18)},()=>({x:Math.random()*cv.width,y:Math.random()*cv.height,vx:(Math.random()-.5)*.4,vy:(Math.random()-.5)*.4}))}
function an(){cx.clearRect(0,0,cv.width,cv.height);const g=cx.createRadialGradient(cv.width*.8,0,0,cv.width*.8,0,cv.width*.8);g.addColorStop(0,"rgba(30,144,255,.18)");g.addColorStop(1,"transparent");cx.fillStyle=g;cx.fillRect(0,0,cv.width,cv.height);
pts.forEach((a,i)=>{a.x+=a.vx;a.y+=a.vy;if(a.x<0||a.x>cv.width)a.vx*=-1;if(a.y<0||a.y>cv.height)a.vy*=-1;cx.fillStyle="#1e90ff";cx.fillRect(a.x,a.y,2,2);for(let j=i+1;j<pts.length;j++){const b=pts[j],d=Math.hypot(a.x-b.x,a.y-b.y);if(d<130){cx.strokeStyle="rgba(30,144,255,"+(1-d/130)*.3+")";cx.beginPath();cx.moveTo(a.x,a.y);cx.lineTo(b.x,b.y);cx.stroke()}}});requestAnimationFrame(an)}
